/**
 * Determines whether the given owner duplicates an existing one. An owner is a duplicate when
 * it shares a telephone number with an existing owner, or when it belongs to the same household
 * &mdash; that is, the same last name and telephone as an existing owner. Names are compared
 * while ignoring letter case and surrounding or repeated whitespace, so {@code "  smith "} and
 * {@code "Smith"} name the same household.
 *
 * @param owner the candidate owner
 * @return {@code true} if an existing owner shares the telephone number or forms the same household
 */
private boolean isDuplicateOwner(Owner owner) {
    return this.clinicService.findAllOwners().stream()
        .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone())
            || isSameHousehold(existing, owner));
}

/**
 * Determines whether two owners form the same household: same telephone number and same last
 * name, where last names are compared ignoring letter case and surrounding or repeated
 * whitespace.
 */
private static boolean isSameHousehold(Owner a, Owner b) {
    return Objects.equals(a.getTelephone(), b.getTelephone())
        && normalizeName(a.getLastName()).equals(normalizeName(b.getLastName()));
}

